"""智能体会话与工具面接口（harness 无关的 HTTP 契约）。"""
from __future__ import annotations

from fastapi import APIRouter

from app.schemas.agent import (
    AgentSessionCreate,
    AgentSessionDeleted,
    AgentSessionRead,
    ToolCallRequest,
    ToolCallResponse,
    TraceRead,
)
from app.services.agent import session as session_store
from app.services.agent import tools as tool_registry
from app.services.agent.session import SESSION_TTL_SECONDS

router = APIRouter()


def _session_read(state) -> AgentSessionRead:
    return AgentSessionRead(
        id=state.id,
        created_at=state.created_at,
        last_active_at=state.last_active_at,
        ttl_seconds=SESSION_TTL_SECONDS,
        object_count=len(state.scene.objects),
        checkpoint_count=len(state.checkpoints),
    )


@router.post("/api/agent/sessions", response_model=AgentSessionRead)
def create_session(request: AgentSessionCreate) -> AgentSessionRead:
    """建会话：上传完整场景快照，智能体后续在服务端副本上迭代。"""
    state = session_store.create_session(request.scene, request.milestones)
    return _session_read(state)


@router.delete("/api/agent/sessions/{session_id}", response_model=AgentSessionDeleted)
def delete_session(session_id: str) -> AgentSessionDeleted:
    deleted = session_store.delete_session(session_id)
    return AgentSessionDeleted(id=session_id, deleted=deleted)


@router.post("/api/agent/sessions/{session_id}/tools/{tool_name}", response_model=ToolCallResponse)
def call_tool(session_id: str, tool_name: str, request: ToolCallRequest) -> ToolCallResponse:
    """统一工具调用入口：未知工具名与非法入参由全局异常处理器统一转 HTTP 响应。"""
    state = session_store.get_session(session_id)
    result, trace_entry = tool_registry.call_tool(state, tool_name, request.params)
    return ToolCallResponse(
        tool=tool_name,
        seq=trace_entry.seq,
        duration_ms=trace_entry.duration_ms,
        result=result.model_dump(),
    )


@router.get("/api/agent/sessions/{session_id}/trace", response_model=TraceRead)
def get_trace(session_id: str) -> TraceRead:
    state = session_store.get_session(session_id)
    return TraceRead(session_id=session_id, entries=state.trace)

