/**
 * 一键微调的**落位规划**（纯函数，无 Vue / Pinia / Three 依赖）。
 *
 * 与 `composables/useIssueActions` 的分工：本文件只回答「该把对象挪到哪个坐标」，
 * 落位、撤销栈、重新校核等副作用全在 composable 里。抽成纯函数是为了让这段几何
 * 能脱离场景单独试算——它的正确性判据是「后端 `/api/validate` 认不认」，
 * 而后端只认坐标，不关心它是怎么算出来的。
 *
 * 阈值一律由调用方传入（取自本次校核结论文本），本文件不含任何默认距离值。
 */
import { clearDistance, footprintHalfExtents, type FootprintLike } from './footprint'
import type { Vec2 } from '../types/scene'

/** 落位吸附步长（m），与拖拽/手柄回写口径一致。 */
export const SNAP = 0.5

/** 外推达标距离之外再留的余量（m）：卡在阈值上时浮点与四舍五入都可能让它重新掉到线下。 */
export const CLEARANCE_MARGIN = 0.2

/** 外推搜索的最大步数；0.5m × 400 = 200m，覆盖场地对角线仍有余。 */
const MAX_PUSH_STEPS = 400

export interface SiteBounds {
  width: number
  depth: number
}

export function snapPosition(position: Vec2): Vec2 {
  return { x: Math.round(position.x / SNAP) * SNAP, z: Math.round(position.z / SNAP) * SNAP }
}

/**
 * 从校核结论文本中解析本次生效的阈值（m）；解析不出返回 null。
 *
 * 后端把生效阈值写作「小于 Xm」「不小于 Xm」，而实测距离写作「…相距 2.1m，建议不小于 5m。」
 * ——故必须以「(不)小于」为锚点取数：直接取文本里第一个数字会取到实测距离，
 * 据此外推等于什么也没修。取最后一处匹配以适应 message / suggestion 两段式句子。
 *
 * 解析失败时调用方须**拒绝自动修复**而不是回落到默认值：回落等同于在前端硬编码
 * 一份阈值表，用户注入规范约束（如「塔吊距基坑不小于 8 米」）后就会把对象推到不达标处。
 */
export function parseLimit(...texts: Array<string | null | undefined>): number | null {
  const pattern = /(?:不小于|小于)\s*([0-9]+(?:\.[0-9]+)?)\s*m/g
  for (const source of texts) {
    if (!source) continue
    const matches = [...source.matchAll(pattern)]
    const last = matches[matches.length - 1]
    if (last) {
      const value = Number(last[1])
      if (Number.isFinite(value) && value > 0) return value
    }
  }
  return null
}

